//
//  AppMarkTests.swift
//  VariorumTests
//
//  13s-b U1a, piece 4 — THE LOGO in the app (her rulings R-13s-24/25: the
//  faithful two-tone striped V, `notes/brand/variorum-v-faithful-red.svg`;
//  Q19 closed — "the app icon + About + the welcome-line mark, nothing
//  more"). The art is generated by `notes/brand/tools/appicon.py` and was
//  checked by eye through Icon Composer's own renderer (`ictool`, the U1a
//  RECORD); these pin what the BUILT bundle carries and the words around it.
//
//  Red on the old tree, by construction: the Mac target's `AppIcon` set was
//  an EMPTY `.appiconset` (Phase 7's pre-created target — slots, no images),
//  so actool wrote no icon file and the bundle had no mark asset at all.
//

import AppKit
import SwiftUI
import Testing
@testable import Variorum

@MainActor
@Suite("13s-b U1a — the logo: the app icon, About, the offer line's mark")
struct AppMarkTests {
    /// The icon is compiled into the bundle: the Icon Composer document's
    /// name in the built Info.plist (actool's partial plist) and the legacy
    /// `.icns` actool derives from it beside the asset catalog's icon stack.
    @Test func theAppIconIsCompiledIntoTheBundle() {
        #expect(Bundle.main.object(forInfoDictionaryKey: "CFBundleIconName") as? String
                == "AppIcon")
        #expect(Bundle.main.url(forResource: "AppIcon", withExtension: "icns") != nil,
                "actool derived the icon file from AppIcon.icon")
    }

    /// ONE small mark, drawn by both of its placements (About and the offer
    /// line), so the two can never wear different art.
    @Test func theMarkIsOneAssetBothPlacementsDraw() throws {
        #expect(AboutCopy.markAssetName == TourOfferCopy.markAssetName)
        let mark = try #require(NSImage(named: AboutCopy.markAssetName),
                                "the mark is in the bundle's asset catalog")
        #expect(abs(mark.size.width - mark.size.height) < 0.5, "a square tile")
    }

    /// The wordmark: lowercase, in real type (TASTE.md's recorded lean —
    /// never generated lettering), in the serif macOS ships (R49).
    @Test func theWordmarkIsLowercaseSerifInRealType() throws {
        #expect(AboutCopy.wordmark == "variorum")
        #expect(AboutCopy.wordmark == AboutCopy.wordmark.lowercased())
        let face = try #require(NSFont(name: AboutCopy.wordmarkFontName, size: 34),
                                "the serif is a shipped face")
        #expect(face.familyName == "Iowan Old Style")
    }

    /// The version line under the word.
    @Test func theVersionLineNamesTheVersionAndTheBuild() {
        #expect(AboutCopy.version(short: "0.9.2", build: "5") == "Version 0.9.2 (5)")
        #expect(AboutCopy.version(short: "0.9.2", build: "") == "Version 0.9.2")
        #expect(AboutCopy.thisAppsVersion.hasPrefix("Version "))
        #expect(AboutCopy.menuTitle == "About Variorum", "the platform's own words")
    }

    /// The window's face lays out around the mark: wider and taller than the
    /// mark itself (the word and the version sit under it), and small — a
    /// panel, not a page.
    @Test func theAboutFaceIsASmallPanelAroundTheMark() {
        let hosting = NSHostingView(rootView: AboutView())
        let size = hosting.fittingSize
        #expect(size.width > AboutView.markSize && size.width < 480,
                "width \(size.width)")
        #expect(size.height > AboutView.markSize + 40 && size.height < 400,
                "height \(size.height)")
    }
}
